import 'package:scan_serve/features/session/data/session_dtos.dart';
import 'package:scan_serve/features/session/domain/session_entities.dart';
import 'package:scan_serve/shared/data/firestore/firestore_metadata_dto.dart';

extension TableSessionDtoMapper on TableSessionDto { TableSession toDomain() => TableSession(id: id, restaurantId: restaurantId, branchId: branchId, tableId: tableId, status: TableSessionStatus.values.byName(status.toLowerCase()), customerCount: customerCount, startedAt: startedAt.toUtc(), endedAt: endedAt?.toUtc(), expiresAt: expiresAt.toUtc(), metadata: metadata.toDomain()); }
extension TableSessionMapper on TableSession { TableSessionDto toDto() => TableSessionDto(id: id, restaurantId: restaurantId, branchId: branchId, tableId: tableId, status: status.name.toUpperCase(), customerCount: customerCount, startedAt: startedAt.toUtc(), endedAt: endedAt?.toUtc(), expiresAt: expiresAt.toUtc(), metadata: FirestoreMetadataDto.fromDomain(metadata)); }
extension CustomerSessionDtoMapper on CustomerSessionDto { CustomerSession toDomain() => CustomerSession(id: id, restaurantId: restaurantId, branchId: branchId, tableId: tableId, tableSessionId: tableSessionId, languageCode: languageCode, deviceId: deviceId, status: CustomerSessionStatus.values.byName(status.toLowerCase()), lastActivityAt: lastActivityAt.toUtc(), expiresAt: expiresAt.toUtc(), metadata: metadata.toDomain()); }
extension CustomerSessionMapper on CustomerSession { CustomerSessionDto toDto() => CustomerSessionDto(id: id, restaurantId: restaurantId, branchId: branchId, tableId: tableId, tableSessionId: tableSessionId, languageCode: languageCode, deviceId: deviceId, status: status.name.toUpperCase(), lastActivityAt: lastActivityAt.toUtc(), expiresAt: expiresAt.toUtc(), metadata: FirestoreMetadataDto.fromDomain(metadata)); }
